{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PHILIPS_SWIGGY_SALES_FACT_ITEMS AS SELECT DISTINCT CONCAT( STORE_ID, \'-\', ITEM_CODE, AREA_NAME, \'-\', UPPER(CITY), \'-\', VARIANT, \'-\', CAST(UNITS_SOLD AS FLOAT), GMV, ORDERED_DATE ) AS ORDER_ID, TO_DATE(LEFT(ORDERED_DATE, 10)) AS ORDER_DATE, CAST(GMV AS FLOAT) AS SELLING_PRICE, UPPER(CITY) AS CITY, UPPER(BRAND) AS BRAND, VARIANT, CAST(BASE_MRP AS FLOAT) AS MRP, STORE_ID, AREA_NAME, ITEM_CODE, CAST(UNITS_SOLD AS FLOAT) AS QUANTITY, UPPER(L2_CATEGORY) AS PRODUCT_CATEGORY, UPPER(L3_CATEGORY) AS PRODUCT_SUB_CATEGORY, UPPER(PRODUCT_NAME) AS PRODUCT_NAME FROM MAPLEMONK.PHILIPS_SWIGGY_SALES ; CREATE OR REPLACE TABLE MAPLEMONK.PHILIPS_SWIGGY_ADS_FACT_ITEMS AS SELECT \'SWIGGY\' AS CHANNEL, \'PRODUCT ADS\' AS AD_TYPE, TRY_CAST(TOTAL_CTR AS FLOAT) AS CTR, COALESCE( TRY_TO_DATE(TRIM(METRICS_DATE), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(METRICS_DATE), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(METRICS_DATE), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(METRICS_DATE), \'MM/DD/YYYY\') ) AS DATE, CAST(0 AS FLOAT) AS VIEWS, TRY_CAST(TOTAL_CLICKS AS FLOAT) AS CLICKS, CAMPAIGN_ID, TRY_CAST(TOTAL_IMPRESSIONS AS FLOAT) AS IMPRESSIONS, PRODUCT_NAME, CAMPAIGN_NAME, CAMPAIGN_STATUS, TRY_CAST(TOTAL_ROI AS FLOAT) * TRY_CAST(TOTAL_BUDGET_BURNT AS FLOAT) AS AD_SALES, TRY_CAST(TOTAL_BUDGET_BURNT AS FLOAT) AS SPEND, \'Manual\' AS TYPE FROM MAPLEMONK.PHILIPS_SWIGGY_ADS ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

